'use client';

import { useState, useEffect } from 'react';
import Container from '../components/ui/Container';
import { ListingsGrid, PropertyCard, ResultsHeader, MapArea } from '../components/features';

interface Property {
  id: string;
  title: string;
  location: string;
  price: number;
  rating: number;
  reviewCount: number;
}

const mockProperties: Property[] = [
  { id: '1', title: 'Casa frente a la playa', location: 'Cancún, México', price: 150, rating: 4.8, reviewCount: 32 },
  { id: '2', title: 'Departamento moderno en la costa', location: 'Playa del Carmen, México', price: 120, rating: 4.6, reviewCount: 28 },
  { id: '3', title: 'Villa de lujo con piscina', location: 'Tulum, México', price: 250, rating: 4.9, reviewCount: 45 },
  { id: '4', title: 'Cabaña rustica frente al mar', location: 'Puerto Vallarta, México', price: 95, rating: 4.5, reviewCount: 19 },
  { id: '5', title: 'Penthouse con vista al océano', location: 'Acapulco, México', price: 180, rating: 4.7, reviewCount: 38 },
  { id: '6', title: 'Bungalow tropical', location: 'Isla Mujeres, México', price: 110, rating: 4.4, reviewCount: 15 },
  { id: '7', title: 'Casa colonial renovada', location: 'Mérida, México', price: 85, rating: 4.3, reviewCount: 12 },
  { id: '8', title: 'Resort privado en la playa', location: 'Los Cabos, México', price: 300, rating: 4.9, reviewCount: 52 },
  { id: '9', title: 'Apartamento de lujo en Riviera Maya', location: 'Riviera Maya, México', price: 160, rating: 4.7, reviewCount: 41 },
  { id: '10', title: 'Casa con jardín tropical', location: 'Puerto Morelos, México', price: 125, rating: 4.5, reviewCount: 23 },
  { id: '11', title: 'Mansión con spa', location: 'Cabo Pulmo, México', price: 320, rating: 4.9, reviewCount: 56 },
  { id: '12', title: 'Estudio moderno frente al mar', location: 'Punta Allen, México', price: 90, rating: 4.2, reviewCount: 10 },
];

export default function Catalog() {
  const [properties, setProperties] = useState<Property[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('asc');

  useEffect(() => {
    setIsLoading(true);
    const timer = setTimeout(() => {
      const sorted = [...mockProperties].sort((a, b) => {
        return sortOrder === 'asc' ? a.price - b.price : b.price - a.price;
      });
      setProperties(sorted);
      setIsLoading(false);
    }, 500);
    
    return () => clearTimeout(timer);
  }, [sortOrder]);

  return (
    <div className="bg-white">
      {/* Results Header with Sort Options */}
      <ResultsHeader total={properties.length} onSortChange={setSortOrder} />

      {/* Main Content Grid */}
      <div className="lg:grid lg:grid-cols-3 lg:gap-6 lg:max-w-7xl lg:mx-auto lg:px-6">
        {/* Listings Column */}
        <div className="lg:col-span-2">
          <ListingsGrid isLoading={isLoading}>
            {properties.map((property) => (
              <PropertyCard
                key={property.id}
                id={property.id}
                title={property.title}
                location={property.location}
                price={property.price}
                rating={property.rating}
                reviewCount={property.reviewCount}
              />
            ))}
          </ListingsGrid>
        </div>

        {/* Map Column - Visible only on desktop */}
        <div className="hidden lg:block sticky top-20 h-fit">
          <MapArea />
        </div>
      </div>

      {/* Mobile Map - Visible only on mobile */}
      <div className="lg:hidden">
        <MapArea />
      </div>
    </div>
  );
}
